        select
          "person_user"."sharedById",
          "person_user"."role",
          "other"."name",
          "other"."birthDate"
        from
          "person" as "other"
          inner join "person_user" on "person_user"."personGroupId" = "other"."personGroupId"
          and "person_user"."sharedById" = "other"."ownerId"
          and "person_user"."sharedWithId" = $1
        where
          "other"."personGroupId" = "person"."personGroupId"
      ) as agg
  ) as "otherPeople",
  (
    select
      coalesce(json_agg(agg), '[]')
    from
      (
        select
          "id",
          "name",
          "email",
          "avatarColor",
          "profileImagePath",
          "profileChangedAt",
          "person_user"."role"
        from
          "person_user"
          inner join "user" on "user"."id" = "person_user"."sharedById"
          and "user"."deletedAt" is null
        where
          "person_user"."personGroupId" = "person"."personGroupId"
          and "person_user"."sharedWithId" = $2
        order by
          "user"."name"
      ) as agg
  ) as "sharedBy",
  (
    select
      coalesce(json_agg(agg), '[]')
    from
      (
        select
          "id",
          "name",
          "email",
          "avatarColor",
          "profileImagePath",
          "profileChangedAt",
          "person_user"."role"
        from
          "person_user"
          inner join "user" on "user"."id" = "person_user"."sharedWithId"
          and "user"."deletedAt" is null
        where
          "person_user"."personGroupId" = "person"."personGroupId"
          and "person_user"."sharedById" = $3
        order by
          "user"."name"
      ) as agg
  ) as "sharedWith"
from
  "person"
where
  "person"."ownerId" = $4
  and f_unaccent ("person"."name") %> (
    select
      f_unaccent ($5)
    where
      set_config('pg_trgm.word_similarity_threshold', '0.5', true) is not null
  )
order by
  f_unaccent ("person"."name") <->>> f_unaccent ($6)
limit
  $7

-- PersonRepository.getDistinctNames
select distinct
  on (lower("person"."name")) "person"."personGroupId",
  "person"."name"
from
  "person"
where
  (
    "person"."ownerId" = $1
    and "person"."name" != $2
  )

-- PersonRepository.getStatistics
select
  count(distinct "visible"."assetId") as "assets"
from
  (
    select
      "asset_face"."assetId"
    from
      "asset_face"
    where
      "asset_face"."deletedAt" is null
      and "asset_face"."isVisible" is true
      and "asset_face"."assetVisibility" = 'timeline'
      and "asset_face"."assetDeletedAt" is null
      and "asset_face"."personGroupId" = $1
      and "asset_face"."ownerId" = any ($2::uuid[])
    union all
    select
      "asset_face"."assetId"
    from
      "asset_face"
    where
      "asset_face"."deletedAt" is null
      and "asset_face"."isVisible" is true
      and "asset_face"."assetVisibility" = 'timeline'
      and "asset_face"."assetDeletedAt" is null
      and "asset_face"."personGroupId" = $3
      and not "asset_face"."ownerId" = any ($4::uuid[])
      and exists (
        select
          1 as "exists"
        from
          "album_asset"
          inner join "album" on "album"."id" = "album_asset"."albumId"
          and "album"."deletedAt" is null
          inner join "album_user" on "album_user"."albumId" = "album"."id"
          and "album_user"."userId" = $5
        where
          "album_asset"."assetId" = "asset_face"."assetId"
      )
  ) as "visible"

-- PersonRepository.createGroup
insert into
  "person_group" ("clusterGroupId")
select
  "user"."clusterGroupId"
from
  "user"
where
  "user"."id" = $1
returning
  *

-- PersonRepository.reassignCluster
begin
update "person_group"
set
  "clusterGroupId" = $1
where
  "person_group"."id" in (
    select
      "person"."personGroupId"
    from
      "person"
    where
      "person"."ownerId" = $2
  )
  and not exists (
    select
      "person"."personGroupId"
    from
      "person"
    where
      "person"."personGroupId" = "person_group"."id"
      and "person"."ownerId" != $3
  )
with
  "shared" as (
    select distinct
      "person"."personGroupId" as "oldId"
    from
      "person"
    where
      "person"."ownerId" = $1
      and exists (
        select
          "other"."personGroupId"
        from
          "person" as "other"
        where
          "other"."personGroupId" = "person"."personGroupId"
          and "other"."ownerId" != $2
      )
  ),
  "mapping" as materialized (
    select
      "shared"."oldId",
      uuid_generate_v4 () as "newId"
    from
      "shared"
  ),
  "created" as (
    insert into
      "person_group" ("id", "clusterGroupId")
    select
      "mapping"."newId",
      $3 as "clusterGroupId"
    from
      "mapping"
  )
select
  "mapping"."oldId",
  "mapping"."newId"
from
  "mapping"
commit

